use serde_json::json;
use std::{collections::BTreeSet,fs};
fn rank(mut a:Vec<Vec<i64>>)->usize{a.retain(|r|r.iter().any(|x|*x!=0));if a.is_empty(){return 0}let mut k=0;for c in 0..a[0].len(){let Some(p)=(k..a.len()).find(|i|a[*i][c]!=0)else{continue};a.swap(k,p);for i in k+1..a.len(){let(x,y)=(a[i][c],a[k][c]);if x!=0{for j in c..a[0].len(){a[i][j]=y*a[i][j]-x*a[k][j]}}}k+=1;}k}
fn rotate(label:&str,shift:usize)->String{if label=="G"{return label.into()}if let Some(e)=label.strip_prefix("G_minus_e"){let d=e.chars().map(|c|(c.to_digit(10).unwrap()as usize-1+shift)%6+1).collect::<Vec<_>>();return format!("G_minus_e{}{}",d[0],d[1])}let mut s=label.strip_prefix("g_").unwrap().chars().map(|c|(c.to_digit(10).unwrap()as usize-1+shift)%6+1).collect::<Vec<_>>();s.sort();format!("g_{}",s.iter().map(ToString::to_string).collect::<String>())}
fn main(){
 let source:serde_json::Value=serde_json::from_str(&fs::read_to_string("../results/six-site-disjoint-pair-triple-source-gate.json").unwrap()).unwrap();
 // Rows are [x,v,w,z | rhs] for L_i=M_i=0 under the two-site rotation.
 let ideals=[[[1,4,1,-6,2],[2,5,-1,-6,6]],[[1,1,4,-6,2],[-1,2,5,-6,6]],[[4,1,1,-6,2],[5,-1,2,-6,6]]];
 for i in 0..3{for j in i+1..3{let rows=ideals[i].iter().chain(ideals[j].iter()).map(|r|r[..4].to_vec()).collect::<Vec<_>>();let aug=ideals[i].iter().chain(ideals[j].iter()).map(|r|r.to_vec()).collect::<Vec<_>>();assert!(rank(aug)>rank(rows));}}
 let completions=source["compatible_source_term_completions"].as_array().unwrap().iter().map(|row|{let mut x=row.as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect::<Vec<_>>();x.sort();x}).collect::<BTreeSet<_>>();
 let mut unseen=completions.clone();let mut orbits=Vec::new();while let Some(seed)=unseen.iter().next().cloned(){let mut orbit=BTreeSet::new();let mut cur=seed;for _ in 0..3{orbit.insert(cur.clone());unseen.remove(&cur);cur=cur.iter().map(|x|rotate(x,2)).collect::<Vec<_>>();cur.sort();}assert_eq!(orbit.len(),3);orbits.push(orbit.into_iter().collect::<Vec<_>>());}
 assert_eq!(orbits.len(),3);
 let packet=json!({"schema":"marici.six_site_disjoint_pair_triple_c3_descent.v1","stabilizer":"C3 generated by rotation by two sites","cartier_components":[{"L":"-2+x-6*z+4*v+w","M":"-6+2*x-6*z+5*v-w"},{"L":"-2+v-6*z+4*w+x","M":"-6+2*v-6*z+5*w-x"},{"L":"-2+w-6*z+4*x+v","M":"-6+2*w-6*z+5*x-v"}],"pairwise_disjoint":true,"cartier_length_per_component":2,"component_action":"free regular C3 permutation","total_cartier_length_per_labelled_orbit":6,"rational_character":{"identity":6,"nonidentity":0},"rational_decomposition":"2*(Q_triv + Q(zeta_3))","source_completion_orbits":orbits,"source_orbit_count":3,"source_orbit_size":3,"descent":"strict on the occurrence-resolved three-component object","single_component_descent":false,"new_carrier_datum":false});
 fs::write("../results/six-site-disjoint-pair-triple-c3-descent.json",serde_json::to_string_pretty(&packet).unwrap()+"\n").unwrap();println!("{}",json!({"cartier_components":3,"total_cartier_length":6,"source_orbits":3,"single_component_descent":false}));
}
